with parsed as (select id, service, host, log_ts, level, latency_ms, context, get_json_object(payload_json, '$.duration') as duration_text, context['trace'] as trace, coalesce(context['trace'], 'direct') as trace_or_default from app_logs) select *, lead(latency_ms) over w_hist next_latency_ms, lag(latency_ms) over w_hist prev_latency_ms, row_number() over w_hist seq_no, first_value(trace, true) over w_ordered first_known_trace from parsed where service = 'search' window w_hist as (partition by host, service order by log_ts asc, id asc), w_ordered as (order by latency_ms asc, id asc rows between unbounded preceding and current row);
